@MvPolynomial.aeval_unique : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R]
  [inst_1 : CommSemiring S₁] [inst_2 : Algebra R S₁] (φ : MvPolynomial σ R →ₐ[R] S₁),
  φ = MvPolynomial.aeval (⇑φ ∘ MvPolynomial.X)

@MvPolynomial.comp_aeval : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R]
  [inst_1 : CommSemiring S₁] [inst_2 : Algebra R S₁] (f : σ → S₁) {B : Type u_4} [inst_3 : CommSemiring B]
  [inst_4 : Algebra R B] (φ : S₁ →ₐ[R] B), φ.comp (MvPolynomial.aeval f) = MvPolynomial.aeval fun i ↦ φ (f i)

@MvPolynomial.aeval_X : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R]
  [inst_1 : CommSemiring S₁] [inst_2 : Algebra R S₁] (f : σ → S₁) (s : σ),
  (MvPolynomial.aeval f) (MvPolynomial.X s) = f s
